ANNOTATIONS = [
    (1, 'before', '''Shell 任务详情弹窗。这个文件把「读文件尾部 → 挂起渲染 → 每秒刷新」串成一条链路，是仓库里 React 19 新特性的集中展示点：use 解包 Promise、Suspense 边界、useDeferredValue 降优先级。同时它复用给监视脚本（kind 为 monitor），所以标题与字段名都带二选一。'''),
    (2, 'before', '''注意 use 与 Suspense 是从 react 直接引入的，不是实验包——说明这套代码运行在支持 React 19 的版本上。useDeferredValue 出现两次依赖（Promise 与列宽），是全文件唯一用来「降优先级」的手段。'''),
    (11, 'before', '''tailFile 只读文件尾部。任务输出可能是几百 MB 的构建日志，整读会先把内存打爆，用户还没看到界面进程就已经死了。'''),
    (12, 'before', '''getTaskOutputPath 与写入端共用同一条路径规则。读端自己拼路径是最常见的错位来源——写入按任务 id 分目录，读端少一层就永远读不到。'''),
    (24, 'before', '''尾读上限 8KB。这个数不是随意取的：按终端每行 80 到 120 列算，8KB 大约对应几十行，正好够看清最后一段报错，又不会让滚动帧率下降。'''),
    (34, 'before', '''异常一律吞成空内容。详情弹窗是排障工具，文件不存在或被删掉时应该显示「无输出」，而不是让整个界面崩在一个读文件的 promise 上。'''),
    (49, 'before', '''组件入口，_c(57)——接近编译器槽数上限的一档，因为这里既要记 20 多个 JSX，又要记若干回调。'''),
    (68, 'before', '''输出内容的 Promise 放进 state，而不是直接 use。原因是要能「换一个新的 Promise」来触发重新读取：React 的 use 只认引用，同一引用不会重跑。'''),
    (69, 'before', '''useDeferredValue 让刷新不阻塞按键。弹窗在持续刷新输出时仍然要能立刻响应 Esc——否则用户会觉得界面卡死，这是「更新很频繁的详情页」必须做的一层。'''),
    (72, 'before', '''只在运行中才起定时器。任务结束后再刷就是纯粹的空转，而这个弹窗常常被留着不关。'''),
    (76, 'before', '''setInterval 的第三参把 shell 塞进回调。这样回调的引用保持稳定，不需要因为 shell 变化而重建定时器——否则每秒都会 clear 再 set 一次，抖动非常明显。'''),
    (93, 'before', '''依赖数组只有任务 id 与状态。shell 对象本身每帧都可能换引用，但只有这两个字段变了才需要重置定时器；依赖写 shell 会导致每秒重建。'''),
    (96, 'before', '''关闭时往对话里回一条 system 消息。别小看这一句：它让「打开过、又关掉了」在记录里留下痕迹，事后回看能分清是没打开还是打开了没看。display 为 system 表示不当作助手发言。'''),
    (108, 'before', '''把 confirm:yes（也就是 Enter）绑定到关闭，context 指定 Confirmation。上下文限定很关键——否则弹窗开着时，其他场景的回车也会被这里截走。'''),
    (127, 'before', '''这个 onKeyDown 处理的是 Dialog 自己不管的三件事：空格关闭、左方向键返回、x 杀进程。也就是说 Dialog 只负责 Esc 与回车，剩下的是业务键，必须在最外层接。'''),
    (138, 'before', '''x 只在 running 时才有效。对已结束的任务发 kill 既无意义，还可能命中已被复用的 id，属于典型的防御性判断。'''),
    (154, 'before', '''kind 为 monitor 时同一个弹窗承担「监视脚本详情」。这是复用而不是分叉：字段几乎相同，只有标题和命令标签换词，分两个组件反而会让样式走偏。'''),
    (157, 'before', '''命令截到 280 宽。超长单行命令在这里被硬截断而不是折行，因为同一行下面还要放状态与时长，撑开会让整个弹窗跳高。'''),
    (167, 'before', '''inputGuide 是底部那行按键说明。exitState.pending 时整行替换成「再按一次退出」——这是双 Esc 防误触机制在上层的约定：第一次按只提示，第二次才真退。'''),
    (184, 'before', '''状态三色：运行中用 background 色（与正文反白）、完成用 success、其余一律 error。退出码只在有值时追加，避免运行中的任务显示成 exit code 未定义。'''),
    (199, 'before', '''endTime 缺失时用 Date.now() 顶替，算出「已经跑了多久」。代价是这个值每秒都在变，因此这一格的缓存依赖是 endTime 而不是整个 shell——运行中每帧重算，结束后才稳定。'''),
    (223, 'before', '''Command 与 Script 二选一。同一个字段在两种任务语义下叫法不同，这是复用组件时最容易被忽略的细节：用户看到的词必须匹配他心里那个概念。'''),
    (267, 'before', '''ShellOutputContent 必须是独立组件。原因是它在 use(promise) 处会挂起，挂起必须有自己的 Suspense 边界——写在父组件里会把整个详情弹窗一起挂掉，连标题都看不见。'''),
    (276, 'before', '''Dialog 的 onCancel 与 handleClose 是同一个函数。Esc、回车确认、空格三条路径最终都落到「回一条 system 消息并关闭」，只有一个实现才好维护。'''),
    (288, 'before', '''最外层 Box 要 tabIndex 加 autoFocus 才能收到键盘事件。终端 UI 里焦点不是自动分配的，谁想接键盘谁就得主动抢——这一行漏了，弹窗就会「显示正常但按键全无反应」。'''),
    (314, 'before', '''没读到内容时给一句话而不是空白。空白会让人以为是渲染失败，而这句话明确区分了「文件里就是空的」。'''),
    (326, 'before', '''取最后 10 行的算法：从尾部往前找换行符，记录 10 个起点再反转顺序。为什么不直接 split 换行——大字符串切分会整份复制，8KB 还好，但这个函数的设计假设是「内容可能比预期长」。'''),
    (335, 'before', '''bytesTotal 大于已读字符数，说明文件比尾部窗口更长、显示的内容是被截断的。这个布尔值唯一的作用就是决定要不要在下面提「共多大」，所以它必须来自读取层而不是猜。'''),
    (364, 'before', '''输出区固定 height 12。高度不随内容跳动，弹窗整体才不会抖；配合 truncate-end，长行从右侧截断，保留命令输出最有效的左侧信息。'''),
    (401, 'before', '''每行单独一个 Text 并挂 index 作 key。行内容会整体滚动替换，用 index 作 key 反而比用内容更稳——内容作 key 会导致每帧全部重建。'''),
]
